  // ================= FX / DOODADS =================
  defSprite('ring', c=>{
    /* Shock front. Two concentric uniform strokes read as a generic flat
       annulus in every runtime capture, so the front is now uneven arc
       segments over one faint coherent band, torn outward into fine frays
       and dragged inward as dim streaks. Seeded LCG, not Math.random: the
       atlas repaints byte-identically after every GL context rebuild, so
       the shockwave art cannot shimmer between recoveries. */
    let seed=0x51AB;
    const rnd=()=>((seed=(seed*1664525+1013904223)>>>0)>>>8)/16777216;
    const R=95;
    c.strokeStyle='#fff'; c.lineCap='round';
    // faint continuous under-band keeps the segments reading as one front
    c.globalAlpha=.28; c.lineWidth=17;
    c.beginPath(); c.arc(0,0,R,0,TAU); c.stroke();
    // angular segmentation: irregular lengths, gaps, widths, radius wobble
    let a=rnd()*TAU; const aEnd=a+TAU-.06;
    while(a<aEnd){
      const len=.13+rnd()*.33, gap=.035+rnd()*.11;
      c.globalAlpha=.5+rnd()*.5; c.lineWidth=8+rnd()*12;
      c.beginPath(); c.arc(0,0,R+(rnd()-.5)*8,a,Math.min(aEnd,a+len)); c.stroke();
      a+=len+gap;
    }
    // radial fraying: fine spokes torn outward off the leading edge
    c.lineCap='butt';
    for(let i=0;i<70;i++){
      const an=rnd()*TAU, r0=R+2+rnd()*5, r1=r0+4+rnd()*13;
      const ca=Math.cos(an), sa=Math.sin(an);
      c.globalAlpha=.12+rnd()*.34; c.lineWidth=1.5+rnd()*2.6;
      c.beginPath(); c.moveTo(ca*r0,sa*r0); c.lineTo(ca*r1,sa*r1); c.stroke();
    }
    // streaked inner falloff: longer, dimmer drag marks toward the origin
    for(let i=0;i<52;i++){
      const an=rnd()*TAU, r1=R-4-rnd()*4, r0=r1-8-rnd()*22;
      const ca=Math.cos(an), sa=Math.sin(an);
      c.globalAlpha=.06+rnd()*.18; c.lineWidth=2+rnd()*3.5;
      c.beginPath(); c.moveTo(ca*r0,sa*r0); c.lineTo(ca*r1,sa*r1); c.stroke();
    }
  });
