    c.fillStyle=lg(c,0,-40,0,90,[[0,'#8b98a2'],[1,'#4a545c']]);
    c.beginPath(); c.roundRect(-100,-64,200,132,12); c.fill();
    c.strokeStyle='#10151a'; c.lineWidth=7; c.stroke();
    // wet dock cutout
    c.fillStyle='#123246'; c.beginPath(); c.roundRect(-58,-36,116,84,10); c.fill();
    c.strokeStyle='#0a1c28'; c.lineWidth=5; c.stroke();
    c.fillStyle='rgba(120,220,255,.25)';
    for(let i=0;i<4;i++) c.fillRect(-52,-24+i*20,104,4);
    // crane
    c.fillStyle='#39424a'; c.fillRect(66,-58,14,96);
    c.fillStyle='#e6c145'; c.fillRect(28,-64,58,10);
    c.fillStyle='#20262b'; c.fillRect(30,-54,6,26);
    // bollards
    rivets(c,[[-88,-52],[-88,56],[88,56],[-70,-52]]);
    c.fillStyle='#fff'; c.fillRect(-100,-64,200,10);
    // hazard edge
    c.save(); c.beginPath(); c.rect(-100,58,200,10); c.clip();
    for(let i=-6;i<7;i++){ c.fillStyle=i%2?'#e6c145':'#1c2126';
      c.beginPath(); c.moveTo(i*26,58); c.lineTo(i*26+18,58); c.lineTo(i*26+6,68); c.lineTo(i*26-12,68); c.fill(); }
