  if(terrainBase)paint(terrainBase.getContext('2d'));
  paint(terrainCanvas.getContext('2d'));
  const k=TS/MAP,r=(kind==='mass'?125:112)*k,sx=clamp(Math.floor(N.x*k-r),0,TS-1),sy=clamp(Math.floor(N.y*k-r),0,TS-1);
