    while(qh<qt){const i=q[qh++],x=i%PGS,y=i/PGS|0;
      for(let k=0;k<4;k++){const nx=x+DX[k],ny=y+DY[k];if(nx<0||ny<0||nx>=PGS||ny>=PGS)continue;
        const n=ny*PGS+nx;if(NAVW[n]&&!NAVCOMP[n]){NAVCOMP[n]=comp;q[qt++]=n;}}
    }
