  arctic:{ground:[.94,.98,1.06],soil:[.91,.95,1.04],pave:[.97,.99,1.03],grass:[.90,.98,1.05]},
  ashland:{ground:[.92,.84,.78],soil:[.94,.82,.70],pave:[.92,.88,.85],grass:[.78,.74,.68]},
  vespera:{ground:[1.03,.91,1.05],soil:[1.02,.88,.94],pave:[.98,.94,1.02],grass:[.91,1.02,.91]}
